// For non-image, non-audio flow
let chatinput = $('Combine & Clear').item.json.chatInput|| " ";
return {
  json: {
    chatInput:chatinput, 
    isFromImage: false,
    isFromAudio: false,
    sessionId: $json.sessionId,
    hasFile: $json.hasFile
  }
};

// Merge all paths: audio transcript, image analysis, or plain text

const input = $json;
return {
  json: {
    chatInput:$json.chatInput,

    sessionId: input.sessionId,
    isFromAudio: input.isFromAudio || false,
    isFromImage: input.isFromImage || false,

    imageAnalysis: input.imageAnalysis || null
  }
};

const text = ($json.content?.parts?.[0]?.text || $('Recover Empty Reply').item.json.output || '').trim();

const recipient = $('Webhook1').item.json.body.entry[0].messaging[0].sender.id;
const isFromAudio = $json.isFromAudio || false;
const isFromImage = $json.isFromImage || false;

// Extract image URLs from ![alt](url) format
const imageRegex = /!\[([^\]]*)\]\((https?:\/\/[^)]+)\)/g;
const images = [];
let match;
while ((match = imageRegex.exec(text)) !== null) {
  images.push({
    alt: match[1],
    url: match[2]
  });
}

// Extract product URLs from [text](url) format
const linkRegex = /\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g;
const links = [];
let linkMatch;
while ((linkMatch = linkRegex.exec(text)) !== null) {
  links.push({
    name: linkMatch[1],
    url: linkMatch[2]
  });
}

// Clean text: remove image markdown, keep readable links
const cleanText = text
  .replace(/!\[[^\]]*\]\([^)]+\)/g, '') // Remove image markdown
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '$1\n$2') // Convert links to readable format
  .replace(/\n{3,}/g, '\n\n') // Remove excessive line breaks
  .trim();

return {
  json: {
    images: images,
    links: links,
    cleanText,
    recipient,
    isFromAudio,
    isFromImage
  }
};

// Messenger webhook -> one clean item. Code of the node "Is valid message1" (name kept: 15+ nodes read its sender/text).
// Bot echoes, deliveries and reads -> stop. route = 'guided' (menus and card buttons, no AI) or 'ai'.
const ONLY_PAGE = '1022637774276560'; // set by the builder per channel ('' = any page); BotGenius answers its test page only
// The webhook item comes from "Final Response1"; this node's input = the customer's stored language row ("Language memory").
const entry = $('Final Response1').first().json.body?.entry?.[0];
const stored = ($input.all().map((i) => i.json).find((r) => r && r.lang) || {}).lang || ''; // 'French' | 'English' | 'darija'
if (ONLY_PAGE && String(entry?.id || '') !== ONLY_PAGE) return [];
const ev = entry?.messaging?.[0];
if (!ev || !(ev.message || ev.postback)) return [];
const msg = ev.message || {};

if (msg.is_echo) {
  if (msg.app_id) return []; // our own bot message
  return [{ json: { status: 'human_reply', text: msg.text || '', sender: ev.sender.id, is_valid: true } }]; // a human agent wrote from the page
}

const att = (msg.attachments || [])[0];
let kind = 'text', text = msg.text || '', payload = '';
if (ev.postback) { kind = 'postback'; payload = String(ev.postback.payload || ''); text = ev.postback.title || payload; }
else if (msg.quick_reply) { kind = 'quick_reply'; payload = String(msg.quick_reply.payload || ''); }
else if (att) { kind = att.type; text = msg.text || ''; } // image/audio/video/file: the base media flow reads the attachment url
text = String(text).trim().slice(0, 1000);

// Card and menu buttons: g|... (guided menus), pick|code, colors|base name. Get Started / a greeting alone -> menu.
// 🎒 Cartables, last tap (gender + level known): the AI takes it, cartable_rules reads ولد/بنت and the level from this text
// Primary school needs the exact year and the school type (cartable_rules picks different models): asked by the menu first.
const bag = payload.match(/^g\|bag\|(boy|girl)\|(?:(rawdha|college|secondaire)|primaire\|([1-6])\|(pub|priv))$/);
const BAG_LEVEL = { rawdha: 'في الروضة', college: 'في الإعدادي', secondaire: 'في الثانوي' };
if (bag) {
  text = `نحب cartable ل${bag[1] === 'boy' ? 'ولد' : 'بنت'} ` + (bag[2] ? BAG_LEVEL[bag[2]]
    : `في السنة ${bag[3]} ابتدائي، مدرسة ${bag[4] === 'pub' ? 'عمومية' : 'خاصة'}`);
}
let guided_id = !bag && /^(g\|(?!order\|)|pick\||colors\||types\||basket\|)/.test(payload) ? payload : '';
// "✅ نكمل الـ commande" on a product (or "🛒 نحب الكل" on a book list): the AI takes the commande, codes as a hidden hint
if (payload.startsWith('g|order|')) {
  const codes = payload.slice(8);
  text = codes.includes(',') ? `نحب نكمل الـ commande بالكتب هذوما الكل، كل واحد نسخة [codes: ${codes}]`
    : `نحب نكمل الـ commande بالمنتوج هذا [code: ${codes}]`;
}
const norm = text.toLowerCase().replace(/[!?.,،؟]+/g, ' ').replace(/\s+/g, ' ').trim();
const GREET = ['salam', 'slm', 'salem', 'salam 3alikom', 'salam alaykom', 'salam 3likom', 'aslema', '3aslema', 'ahla', 'ahlan', 'marhba',
  'bonjour', 'bonsoir', 'salut', 'hello', 'hi', 'hey', 'menu', 'القائمة', 'السلام عليكم', 'سلام', 'عسلامة', 'اهلا', 'أهلا', 'مرحبا', 'start'];
if (!guided_id && (payload === 'GET_STARTED' || (kind === 'text' && GREET.includes(norm)))) guided_id = 'g|menu';

// Reply language, one per customer: a clear message (darija in Arabic letters or Arabizi, French, English) sets it and is
// stored ("Remember language"); a tap or a neutral message (name, phone, city, "ok") keeps the stored one. Default: darija.
const low = ` ${text.toLowerCase().replace(/[!?.,،؟]+/g, ' ')} `;
const words = (list) => list.filter((w) => low.includes(` ${w} `)).length;
const arabizi = /[a-z][2379]|[2379][a-z]/i.test(text)
  || words(['salam', 'aslema', 'ahla', 'n7eb', 'nheb', 'chnowa', 'chnia', '3andkom', 'andkom', 'behi', 'barcha', 'mta3', 'fama', 'chlaka', 'bkadech', 'b9adech', 'wala', 'ey', 'yesser', 'inchallah', 'slm', 'bech']) > 0;
const fr = words(['bonjour', 'bonsoir', 'salut', 'je', 'vous', 'avez', 'prix', 'merci', 'svp', 'est', 'pour', 'des', 'les', 'une', 'cherche', 'voudrais', 'combien', 'livre', 'cahier', 'cahiers', 'oui', 'non', "d'accord"]);
const en = words(['hello', 'hi', 'hey', 'the', 'do', 'you', 'have', 'want', 'price', 'please', 'how', 'much', 'book', 'pens', 'looking', 'yes', 'thanks']);
let clear = ''; // '' = neutral
if (kind === 'text' && !bag && !payload.startsWith('g|order|')) {
  if (/[؀-ۿ]/.test(text) || arabizi) clear = 'darija';
  else if (fr >= 1 && fr >= en) clear = 'French';
  else if (en >= 1) clear = 'English';
}
const now = clear || stored || 'darija';
const lang = now === 'darija' ? 'Tunisian darija in Arabic letters' : now;
const remember = clear && clear !== stored ? clear : '';

return [{ json: {
  is_from: 'Facebook', status: 'user_message', is_valid: true,
  sender: ev.sender.id, psid: ev.sender.id, page_id: ev.recipient?.id || '', kind, text, payload, lang, remember,
  // a video or a real photo of a product: only the shop team can film it -> always handed to the CM (build: patch_media_request)
  media_request: kind === 'text' && /(فيديو|ڤيديو|vid[ée]o|\bfidyo\b|(تصاور|صور|صورة|تصويرة)\s*(حقيقي|reel|réel)|(vraie?s?|r[ée]elles?)\s*photos?|photos?\s*r[ée]elles?|real\s*(photo|picture|image)|tsawer\s*(reel|r[ée]el|7a9i9i))/i.test(text),
  route: guided_id ? 'guided' : 'ai', guided_id,
  // typed text is grouped with the next messages (buffer); button taps and media are answered at once
  mid: msg.mid || ev.postback?.mid || '', ts: Date.now(), typed: kind === 'text' ? 'yes' : 'no',
} }];

const senderId = $('Is valid message1').item.json.sender?.id
  || $('Is valid message1').item.json.sender
  || 'unknown';

const sessionId =
  $json.sessionId ||
  $json.body?.sessionId ||
  $json.headers?.['x-session-id'] ||
  'sess_' + senderId;

const hasFile = !!($binary && Object.keys($binary || {}).length > 0);

const lastMessage = $('If').item.json.last_message || '';
const hasURL = /https?:\/\/[^\s]+/.test(lastMessage);

const hasAudio = $json.type === 'audio' || ($json.messages?.[0]?.type === 'audio');

const rawInput = ($json.chatInput || $json.body?.chatInput || '').trim();

let chatInput;
if (rawInput) {
  chatInput = rawInput;
} else if (hasURL) {
  chatInput = '(User sent a link — open/identify the product and respond)';
} else if (hasFile) {
  chatInput = '(User sent an image without text — analyze it and suggest matching products)';
} else if (hasAudio) {
  chatInput = '(User sent a voice message — transcribe and respond naturally)';
} else {
  chatInput = 'empty';
}

const outputItem = {
  json: { chatInput, sessionId, hasFile, hasAudio, hasURL }
};

if (hasFile && $binary) {
  outputItem.binary = $binary;
}

return outputItem;

// Shape data for the Human Handoff Manager sub-workflow
const ask = $('Is valid message1').first().json;
// photo/video request: the CM must film the product; the token at the END makes the handoff manager escalate
const aiOutput = ask.media_request && !/\[\[ESCALATE\]\]\s*$/.test($json.cleanText || '')
  ? `📸 Demande photo/vidéo réelle: "${String(ask.text).slice(0, 200)}"\n${($json.cleanText || '').replace(/\[\[ESCALATE\]\]/g, '')} [[ESCALATE]]`
  : ($json.cleanText || '');

// Simple error heuristic: if output is suspiciously short, flag it
const errorCount = aiOutput.trim().length < 5 ? 1 : 0;

// Real name from the Facebook profile ("Sender name" node); empty if unavailable.
let customerName = '';
try {
  const s = $('Sender name').first().json;
  customerName = [s.first_name, s.last_name].filter(Boolean).join(' ').trim();
} catch (e) {}

return {

    aiOutput: aiOutput,
    userId: $json.recipient,
    platform: 'Facebook',
    phoneNumberId: $json.recipient,
    customerName: customerName,
    customerMessage: String(ask.text || '').slice(0, 300),
    errorCount: errorCount

};

const transcript = $json.candidates[0].content.parts[0].text|| '';


if (!transcript) {
  return {
    json: { 
      chatInput: "Sorry, I couldn't understand the audio. Please try again.",
      isFromAudio: false
    }
  };
}

return {
  json: {
    chatInput: transcript,
    isFromAudio: true,

  }
};

