const senderId = $('Is valid message1').item.json.sender;

return {
  json: {
    name: `user_${senderId}`,
    sender_id: senderId,
    id: senderId
  }
};

const sender = $('Is valid message1').item.json.sender;
const text = $('Is valid message1').item.json.text||$('Final Response1').first().json.body.entry[0].messaging[0].message?.attachments?.[0].payload.url || 'empty';

return {
  json: {
    sender_id: sender,
    last_message: text,
    last_seen: new Date().toISOString()
  }
};

const prev = $('Classify Input1').first()?.json || {};

let raw =
  $json.text ||
  $json.response?.text ||
  $json.candidates?.[0]?.content?.parts?.[0]?.text ||
  $json.content?.parts?.[0]?.text ||
  '';

raw = raw.replace(/```json|```/g, '').trim();

let analysis = null;

try {
  analysis = JSON.parse(raw);
} catch (e) {
  analysis = {
    clarity: 'unclear',
    rawResponse: raw
  };
}

const unclear =
  !analysis ||
  analysis.clarity === 'unclear';

const hasChatInput =
  $json.chatinput !== null &&
  $json.chatinput !== undefined &&
  $json.chatinput !== '';

const uploadedImageUrl = prev.imageUrl || null;

const visualHint = uploadedImageUrl
  ? ` | UPLOADED_IMAGE_URL: ${uploadedImageUrl} (call visual_search with this exact URL as image_url to find visually similar products)`
  : '';

const ChatInput = hasChatInput
  ? $json.chatinput
  : (
      unclear
        ? 'Ask user for a clearer image in (french or tunisien ) based on the user '
        : `Analyze product: ${JSON.stringify(analysis)} | ${prev.shopifyTitle || ''}${visualHint}`
    );

return {
  json: {
    sessionId: prev.sessionId || null,
    inputType: prev.inputType || null,
    analysis,
    needsBetterPhoto: unclear,
    uploadedImageUrl,
    chatInput: ChatInput
  }
};

const msg = $('Final Response1').item.json.body.entry?.[0]?.messaging?.[0] || {};

const message = msg.message || {};
const attachments = message.attachments || [];
const text = message.text || '';

let inputType = 'none';
let imageUrl = null;
let shopifyUrl = null;
let postUrl = null;
let postTitle = null;

// Image
const imageAttachment = attachments.find(a => a.type === 'image' && a.payload?.url);
if (imageAttachment) {
  inputType = 'image';
  imageUrl = imageAttachment.payload.url;
}

// Facebook post
const postAttachment = attachments.find(a => a.type === 'post');
if (postAttachment) {
  inputType = 'facebook_post';
  postUrl = postAttachment.payload?.url || null;
  postTitle = postAttachment.payload?.title || null;
}

// Shopify link
const urlMatch = text.match(/https?:\/\/[^\s]+/);
const linkUrl = urlMatch ? urlMatch[0] : null;

if (linkUrl && linkUrl.includes('/products/')) {
  inputType = 'shopify';

  const cleanUrl = linkUrl.split('?')[0].replace(/\/$/, '');
  shopifyUrl = cleanUrl.endsWith('.json')
    ? cleanUrl
    : `${cleanUrl}.json`;
}

return {
  json: {
    attachments,
    inputType,
    imageUrl,
    postUrl,
    postTitle,
    shopifyUrl,
    chatInput: text,
    isFromImage: inputType === 'image',
    sessionId: $json.sessionId,
    hasFile: $json.hasFile
  }
};

const p = $json.product;
const prev = $('Classify Input1').item.json;

if (!p) {
  return { json: { ...prev, imageUrl: null, shopifyFailed: true } };
}

return {
  json: {
    ...prev,
    imageUrl: p.images?.[0]?.src || p.image?.src || null,
    shopifyTitle: p.title || null,
    shopifyVendor: p.vendor || null,
    shopifyType: p.product_type || null,
    shopifyPrice: p.variants?.[0]?.price || null
  }
};

const sender = $('Is valid message1').item.json.sender;
const text = $('Is valid message1').item.json.text || '';
const token = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

return {
  json: {
    sender_id: 'fb_' + sender,
    psid: sender,
    token,
    text
  }
};

const doc = $json;
let raw = doc.messages;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = []; } }
const messages = Array.isArray(raw) ? raw : [];
const combined = messages.join('\n');

return {
  json: {
    chatInput: combined,
    sender_id: $('Set Token').item.json.sender_id,
    psid: $('Set Token').item.json.psid
  }
};

// Loop over input items and add a new field called 'myNewField' to the 

let chatinput = "chercher se produit " + $('Router').first().json.attachments[0].payload.product.elements[0].title + ' prix ' + $('Router').first().json.attachments[0].payload.product.elements[0].subtitle + " Describtion : "+ $input.first().json.content.parts[0].text


return {chatinput:chatinput}

// Merge fresh message data with any existing AI-control state.
// First contact -> no prior doc -> stamp ai_enabled explicitly true.
// Returning sender -> keep whatever ai_enabled/disabled_by/escalated_at a human already set.
const fresh = $('Code in JavaScript1').item.json;
const existing = $json || {};
const hadDoc = existing.sender_id !== undefined;

return {
  json: {
    sender_id: fresh.sender_id,
    last_message: fresh.last_message,
    last_seen: fresh.last_seen,
    ai_enabled: hadDoc ? (existing.ai_enabled !== false && Number(existing.ai_enabled) !== 0) : true,
    disabled_by: hadDoc ? (existing.disabled_by ?? null) : null,
    escalated_at: hadDoc ? (existing.escalated_at ?? null) : null
  }
};

// Custom chat memory (replaces the MongoDB Chat Memory node).
// Input: the last 30 rows (= 15 exchanges) from the messages table, oldest first.
// Output: the get_prompt item + historyBlock, read by the agent system message.
const base = $('Get Prompt').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.content);
const clip = (t) => { t = String(t); return t.length > 1500 ? t.slice(0, 1500) + '...' : t; };

let historyBlock = '';
if (rows.length) {
  historyBlock =
    '=== HISTORIQUE RECENT DE LA CONVERSATION (du plus ancien au plus recent) ===\n' +
    rows.map(r => (r.role === 'ai' ? 'Assistant: ' : 'Client: ') + clip(r.content)).join('\n') +
    '\n=== FIN HISTORIQUE ===';
}

return [{ json: { ...base, historyBlock }, pairedItem: { item: 0 } }];

// The agent sometimes returns output = '' : Gemini wrote the answer in an earlier turn together
// with a tool call, then answered the tool result with an empty turn. Take the last non-empty text.
const item = $input.first().json;
const textOf = (c) => {
  if (typeof c === 'string') return c;
  if (Array.isArray(c)) return c.map(p => (typeof p === 'string' ? p : (p && p.text) || '')).join('');
  return '';
};

let output = String(item.output || '').trim();
let source = 'agent';
if (!output) {
  const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];
  for (let i = steps.length - 1; i >= 0 && !output; i--) {
    const log = (steps[i].action && steps[i].action.messageLog) || [];
    for (let j = log.length - 1; j >= 0 && !output; j--) {
      const m = log[j] || {};
      output = textOf((m.kwargs && m.kwargs.content) ?? m.content).trim();
    }
    if (!output && steps[i].action && steps[i].action.log) {
      const l = String(steps[i].action.log);
      if (!/^Invoking "/.test(l)) output = l.trim();
    }
  }
  source = output ? 'recovered' : 'fallback';
}
if (!output) {
  output = "Desole, je n'ai pas bien saisi. Pouvez-vous reformuler votre question ?";
}

// tool steps kept: Build reply reads the cards' product data from them
return [{ json: { output, reply_source: source, intermediateSteps: item.intermediateSteps || [] }, pairedItem: { item: 0 } }];

// Shared by "Build reply" (fb_cards.js) and "Guided cards" (guided_cards.js): the build puts this file in front of them.
// Product card from Qdrant/tool data + color words ("other colors" = same name without its color words).
const COLOR_WORDS = ['NOIR', 'NOIRE', 'BLANC', 'BLANCHE', 'GRIS', 'GRISE', 'BLEU', 'BLEUE', 'ROUGE', 'VERT', 'VERTE', 'ROSE', 'JAUNE', 'ORANGE',
  'VIOLET', 'VIOLETTE', 'BEIGE', 'MARRON', 'KAKI', 'MARINE', 'CIEL', 'TURQUOISE', 'FUCHSIA', 'DORE', 'DOREE', 'ARGENT', 'ARGENTE', 'OR', 'BORDEAUX',
  'LILAS', 'MAUVE', 'CORAIL', 'PISTACHE', 'MENTHE', 'FLUO', 'CLAIR', 'FONCE', 'BLACK', 'WHITE', 'BLUE', 'RED', 'GREEN', 'PINK', 'YELLOW',
  'PURPLE', 'GREY', 'GRAY', 'BROWN', 'أسود', 'أبيض', 'أزرق', 'أحمر', 'أخضر', 'وردي', 'أصفر', 'بنفسجي', 'رمادي', 'بني'];
const COLOR_RE = new RegExp(`(?<=^|[\\s/,-])(?:${COLOR_WORDS.join('|')})(?=$|[\\s/,-])`, 'g');
const upper = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
const hasColor = (name) => upper(name).replace(COLOR_RE, '\u0000').includes('\u0000');
// Model name = the words before the first color word ("... STABILO POINT 88 GRIS FONCE 88/98" -> "... STABILO POINT 88"):
// it is a substring of every color of the model, so it also works as the Qdrant text search.
const baseName = (name) => {
  const u = upper(name);
  const m = new RegExp(COLOR_RE.source).exec(u);
  return (m ? u.slice(0, m.index) : u).replace(/[\s/,-]+$/, '').replace(/\s+/g, ' ').trim();
};
// "Other types" = models whose name starts with the same words ("STYLO BIC ...", "CNP 3E SEC ...").
// shortcut: name prefix, products have no type tags yet; upgrade with the search v2 tags
const typeKey = (name) => {
  const w = baseName(name).split(/[\s/,()-]+/).filter((x) => x.length >= 2);
  return w.slice(0, w[0] === 'CNP' ? 3 : 2).join(' ');
};

const num = (x) => parseFloat(String(x ?? '').replace(',', '.')) || 0;
const dt = (n) => n.toFixed(3) + ' DT';
const https = (u) => (/^https:\/\//.test(String(u || '')) ? String(u) : '');
// Product photos: only the shop's image server. The catalog sync wrote 2,238 placeholders (https://cdn.example.com/...).
const photo = (u) => (/^https:\/\/([a-z0-9-]+\.)*lebosphore\.tn\//i.test(String(u || '')) ? String(u) : '');
const isActive = (d) => !(d.active === false || String(d.active) === '0');
const labels = (arUi) => (arUi
  ? { pick: '✅ نختار هذا', colors: '🎨 ألوان أخرى', site: '🔗 الموقع', before: 'avant' } // an Arabic word inside "x DT" is reordered by Messenger
  : { pick: '✅ Je choisis', colors: '🎨 Autres couleurs', site: '🔗 Voir le site', before: 'avant' });
const subtitle = (d, arUi) => {
  const now = num(d.price), before = num(d.compare_price);
  const line = before > now && now > 0
    ? `🏷️ -${Math.round(100 - (now * 100) / before)}% ➜ ${dt(now)} (${labels(arUi).before} ${dt(before)})`
    : `💰 ${dt(now)}`;
  return d.promo?.designation ? `${line}\n🎁 ${d.promo.designation}` : line;
};
// Buttons (max 3): pick, other colors (only when the name has a color word), site.
const card = (code, d, arUi, { pick = true } = {}) => {
  const L = labels(arUi);
  const url = https(d.productUrl);
  const c = { title: d.name, subtitle: subtitle(d, arUi), buttons: [] };
  if (pick) c.buttons.push({ type: 'postback', title: L.pick, payload: `pick|${code}` });
  if (pick && hasColor(d.name)) c.buttons.push({ type: 'postback', title: L.colors, payload: `colors|${baseName(d.name)}` });
  if (photo(d.image)) c.image_url = photo(d.image);
  if (url) { c.url = url; c.buttons.push({ type: 'web_url', title: L.site, url }); }
  return c;
};

// Turn the agent reply into Messenger parts, in this order: intro text -> product carousel -> question (+ quick replies) LAST.
// (Messenger shows quick replies only under the newest message, so the question must come after the cards.)
// Agent line formats:
//   CARD: <code>                       product card; name, price, photo and link come from this turn's tool results
//   BUTTONS: option 1 | option 2 | ... quick replies under the question
//   SUMMARY / CONFIRMATION             placeholders for the exact code-built commande blocks (Order_product_shopify)
//   REFS: ...                          hidden memory for the agent, never sent
const reply = $('Recover Empty Reply').first().json; // the answer used (first agent or its retry) + its tool steps
const agentOut = String(reply.output || '');
const steps = reply.intermediateSteps || [];
const msg = $('Is valid message1').first().json;
const psid = msg.psid || msg.sender;
const AR_UI = !/^(French|English)/.test(msg.lang || '');

// Internal hints for the AI must never reach the customer, even if the AI copies them.
const HIDDEN = [
  /\[\s*(ref|code|model|context)\s*:[^\]\n]*\]/gi, // [ref: x] [code: x] [model: x] [context: ...]
  /\[?\s*\b(reply in|system check)\b\s*:[^\]\n]*\]?(\s*\((never|default)[^)\n]*\))?/gi, // [reply in: ...] with or without [
  /\[\[ESCALATE\]\]/g,
];
const raw = HIDDEN.reduce((t, re) => t.replace(re, ''), agentOut).replace(/[ \t]+\n/g, '\n').trim();

// ---- product data from the tool results of this turn (vector_search: result[], get_promo: eligible_products[]) ----
const products = {};
const texts = [];
const collect = (v) => {
  if (typeof v === 'string') { try { collect(JSON.parse(v)); } catch (e) { texts.push(v); } return; }
  if (Array.isArray(v)) { v.forEach(collect); return; }
  if (!v || typeof v !== 'object') return;
  const name = v.name || v.product_name;
  if (v.code != null && name) {
    const d = products[String(v.code)] || {};
    for (const [k, x] of Object.entries({ ...v, name })) if (x !== null && x !== undefined && x !== '' && d[k] === undefined) d[k] = x;
    products[String(v.code)] = d;
  }
  Object.values(v).forEach(collect);
};
steps.forEach((s) => collect(s.observation));
let summary = '', confirmation = '';
for (const t of texts) {
  if (t.startsWith('PREVIEW OK')) summary = t.slice(t.indexOf('\n') + 1).trim(); // exact summary from Order_product_shopify
  if (t.startsWith('ORDER CREATED')) confirmation = t.slice(t.indexOf('\n') + 1).trim(); // exact confirmation
}

// card(), isActive() come from card_lib.js (put in front of this file by the build)
const L = { choose: AR_UI ? 'اختار من فضلك 👇' : 'Choisissez 👇' };

// ---- read the agent lines ----
// Money comes only from the cards and the code blocks: the AI's own price/total lines and image markdown are dropped.
const MONEY = /(المجموع|💳|🧾|السعر\s*:|\bTotal\s*:|Sous-total|Récapitulatif|\d+(?:[.,]\d{1,3})?\s*(DT|TND|dinars?|دينار|دنانير|د\.ت))/i;
const cards = [], intro = [], outro = [];
let buttons = [], summaryUsed = false, confirmationUsed = false;
for (const line of raw.split('\n')) {
  if (/^\s*REFS:/i.test(line) || /^\s*!\[[^\]]*\]\([^)]*\)\s*$/.test(line)) continue;
  const b = line.match(/^\s*BUTTONS:\s*(.+)$/i);
  if (b) { buttons = [...new Set(b[1].split('|').map((t) => t.trim()).filter(Boolean))].slice(0, 13); continue; }
  const c = line.match(/^\s*CARD:\s*([^|\s]+)/i);
  if (c) {
    const d = products[c[1]];
    if (d && isActive(d) && cards.length < 10 && !cards.some((x) => x.code === c[1])) cards.push({ code: c[1], ...card(c[1], d, AR_UI) });
    continue;
  }
  if (/^\s*SUMMARY\s*$/i.test(line)) { if (summary) (cards.length ? outro : intro).push(summary); summaryUsed = true; continue; }
  if (/^\s*CONFIRMATION\s*$/i.test(line)) { if (confirmation) intro.push(confirmation); confirmationUsed = true; continue; }
  if (MONEY.test(line)) continue;
  (cards.length ? outro : intro).push(line);
}
// The AI forgot the placeholder: the code block is shown anyway, at the top.
if (confirmation && !confirmationUsed) intro.unshift(confirmation);
if (summary && !summaryUsed && !confirmation) intro.unshift(summary);

// Messenger shows no markdown: remove bold/italic markers, keep links readable.
const clean = (lines) => lines.join('\n')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1: $2')
  .replace(/\*\*([^*\n]+)\*\*/g, '$1').replace(/__([^_\n]+)__/g, '$1')
  .replace(/^[ \t]*[-*•][ \t]+/gm, '• ')
  .replace(/\*([^*\n]+)\*/g, '$1').replace(/~([^~\n]+)~/g, '$1')
  // Tunisian shop words (owner): "قرعة" is Algerian -> "دبوزة ماء"; never "طلبية" -> "commande"
  .replace(/(ال)?قرعة( ماء| متاع الماء)?/g, 'دبوزة ماء').replace(/(ال)?طلبي(ة|ات)/g, 'commande')
  .replace(/\n{3,}/g, '\n\n').trim();

// ---- cartable fit, enforced by code (staff: "SB01-XL = 1ère-3ème étatique"; the AI had offered it for a 5ème) ----
// model -> levels from cartable_rules, filled by the build. A model that does not fit the child's level is never shown.
const CARTABLE_FIT = {"SBJ01": {"publique": ["Rawdha"], "privée": ["Rawdha"]}, "TLJ02": {"publique": ["Prépa"], "privée": ["Prépa"]}, "SB02": {"publique": ["1ère", "2ème", "3ème"], "privée": ["1ère"]}, "SB01-XL": {"publique": ["1ère", "2ème", "3ème"], "privée": ["1ère"]}, "SBL01": {"publique": ["1ère", "2ème"], "privée": []}, "SBL02": {"publique": ["3ème", "4ème"], "privée": ["1ère", "2ème", "3ème"]}, "SBH02": {"publique": ["3ème", "4ème"], "privée": ["2ème", "3ème"]}, "SB03": {"publique": ["4ème", "5ème", "6ème"], "privée": ["3ème", "4ème"]}, "SB02-XL": {"publique": ["4ème", "5ème", "6ème"], "privée": ["3ème", "4ème"]}, "SBL03": {"publique": ["5ème", "6ème"], "privée": ["3ème", "4ème"]}, "SBH03": {"publique": ["5ème", "6ème"], "privée": ["3ème", "4ème", "5ème", "6ème"]}, "SD01": {"publique": ["7ème", "8ème"], "privée": ["7ème", "8ème"]}, "SD02": {"publique": ["7ème", "8ème", "9ème"], "privée": ["7ème", "8ème", "9ème"]}, "SD03": {"publique": ["7ème", "8ème", "9ème", "Secondaire"], "privée": ["7ème", "8ème", "9ème", "Secondaire"]}, "SDI": {"publique": ["Secondaire"], "privée": ["Secondaire"]}, "SDIC": {"publique": ["Secondaire"], "privée": ["Secondaire"]}};
const said = (() => { try { return String($('Merge Input Paths1').first().json.chatInput || ''); } catch (e) { return ''; } })();
const prof = (() => { try { return $('Load customer').first().json || {}; } catch (e) { return {}; } })();
const gradeOf = (t) => {
  const s = ` ${String(t || '').toLowerCase()} `;
  if (/روضة|rawdha/.test(s)) return 'Rawdha';
  if (/تحضيري|pr[eé]pa/.test(s)) return 'Prépa';
  if (/ثانوي|secondaire|lyc[eé]e/.test(s)) return 'Secondaire';
  const AR = [['الأولى|الاولى|أولى|اولى', 1], ['الثانية|ثانية', 2], ['الثالثة|ثالثة', 3], ['الرابعة|رابعة', 4], ['الخامسة|خامسة', 5],
    ['السادسة|سادسة', 6], ['السابعة|سابعة', 7], ['الثامنة|ثامنة', 8], ['التاسعة|تاسعة', 9]];
  let n = (AR.find(([w]) => new RegExp(w).test(s)) || [])[1];
  if (!n) n = Number((s.match(/([1-9])\s*(?:ère|ere|ème|eme|e)(?![a-zà-ÿ])/) || s.match(/(?:السنة|سنة|sana|classe|année|annee)\s*([1-9])(?!\d)/) || [])[1]) || 0;
  return n ? (n === 1 ? '1ère' : `${n}ème`) : '';
};
const schoolOf = (t) => (/عموم|[ée]tatique|publi/i.test(t) ? 'publique' : /خاص|priv/i.test(t) ? 'privée' : '');
const grade = gradeOf(said) || gradeOf(prof.child_level);
const school = schoolOf(said) || schoolOf(prof.school_type);
const MODELS = Object.keys(CARTABLE_FIT).sort((a, b) => b.length - a.length); // SB02-XL before SB02
const modelOf = (name) => MODELS.find((k) => new RegExp(`(^|[^A-Z0-9])${k.replace(/[-]/g, '\\-')}($|[^A-Z0-9])`).test(String(name).toUpperCase()));
const levelsOf = (m) => (school ? CARTABLE_FIT[m][school] : [...CARTABLE_FIT[m].publique, ...CARTABLE_FIT[m]['privée']]);
const dropped = [];
if (grade && MODELS.length) {
  for (let i = cards.length - 1; i >= 0; i--) {
    const m = modelOf(cards[i].title);
    if (m && !levelsOf(m).includes(grade)) { if (!dropped.includes(m)) dropped.unshift(m); cards.splice(i, 1); }
  }
}
if (dropped.length) {
  const S = AR_UI ? { publique: 'عمومية', 'privée': 'خاصة' } : { publique: 'publique', 'privée': 'privée' };
  const made = (m) => ['publique', 'privée'].filter((k) => CARTABLE_FIT[m][k].length).map((k) => `${S[k]} ${CARTABLE_FIT[m][k].join(', ')}`).join(' | ');
  const good = MODELS.filter((k) => levelsOf(k).includes(grade)).sort();
  const lvl = grade + (school ? ` (${S[school]})` : '');
  intro.length = 0; // the AI's own claim ("يجيو قد ولدك") is removed with the card
  intro.push(...dropped.map((m) => (AR_UI ? `⚠️ ${m} معمول ل: ${made(m)}، موش ل${lvl}.` : `⚠️ ${m} est fait pour : ${made(m)}, pas pour ${lvl}.`)));
  if (good.length) intro.push(AR_UI ? `🎒 الموديلات المناسبة ل${lvl}: ${good.join(', ')}` : `🎒 Modèles adaptés à ${lvl} : ${good.join(', ')}`);
}

const out = [];
const replies = buttons.map((t) => ({ title: t, payload: `qr|${t}` }));
const question = (text) => (replies.length ? { kind: 'quick_replies', psid, text: text || L.choose, replies } : text && { kind: 'text', psid, text });
if (cards.length) {
  if (clean(intro)) out.push({ kind: 'text', psid, text: clean(intro) });
  out.push({ kind: 'carousel', psid, cards: cards.map(({ code, ...c }) => c) });
  const q = question(clean(outro));
  if (q) out.push(q);
} else {
  const q = question(clean([...intro, ...outro]));
  if (q) out.push(q);
}
if (!out.length) {
  out.push({ kind: 'text', psid, text: AR_UI ? 'نعتذرو، صار مشكل تقني. عاود ابعثلنا رسالتك بعد شوية من فضلك.'
    : 'Désolé, un problème technique est survenu. Merci de renvoyer votre message dans un instant.' });
}
return out.map((json) => ({ json }));

// Reply parts -> exact Messenger Send API bodies, in the same order. One output item = one POST to /me/messages.
// In: { kind: 'text'|'quick_replies'|'carousel'|'image', psid, text, replies[{title,payload}], cards[{title,subtitle,image_url,url,buttons}], url }
// Limits: text 2000, quick replies 13 (title 20), generic template 10 elements (title/subtitle 80, 3 buttons).
const cut = (s, n) => {
  s = String(s ?? '').trim();
  if (s.length <= n) return s;
  let out = '';
  for (const ch of s) { if (out.length + ch.length > n - 1) break; out += ch; } // never splits an emoji
  return out.trimEnd() + '…';
};

// Split on paragraphs, then lines, then hard cut; every part <= 2000.
function split(text, max = 2000) {
  const parts = [];
  let cur = '';
  const push = (s) => { if (s.trim()) parts.push(s.trim()); };
  for (const para of String(text ?? '').split(/\n{2,}/)) {
    const add = cur ? `${cur}\n\n${para}` : para;
    if (add.length <= max) { cur = add; continue; }
    push(cur); cur = '';
    let rest = para;
    while (rest.length > max) {
      let at = rest.lastIndexOf('\n', max);
      if (at < max / 2) at = max;
      push(rest.slice(0, at)); rest = rest.slice(at);
    }
    cur = rest;
  }
  push(cur);
  return parts;
}

const body = (psid, message) => ({ json: { body: { recipient: { id: String(psid) }, messaging_type: 'RESPONSE', message } } });

const out = [];
for (const { json: p } of $input.all()) {
  if (p.kind === 'text' || p.kind === 'quick_replies') {
    const parts = split(p.text);
    const replies = (p.replies || []).slice(0, 13).map((r) => ({ content_type: 'text', title: cut(r.title, 20), payload: String(r.payload).slice(0, 1000) }));
    if (p.kind === 'quick_replies' && !parts.length && replies.length) parts.push('👇');
    parts.forEach((t, i) => {
      const last = i === parts.length - 1;
      out.push(body(p.psid, p.kind === 'quick_replies' && last && replies.length ? { text: t, quick_replies: replies } : { text: t }));
    });
  } else if (p.kind === 'carousel') {
    const elements = (p.cards || []).slice(0, 10).map((c) => {
      const e = { title: cut(c.title, 80) || 'Le Bosphore' };
      if (c.subtitle) e.subtitle = cut(c.subtitle, 80);
      if (c.image_url) e.image_url = c.image_url;
      if (c.url) e.default_action = { type: 'web_url', url: c.url, webview_height_ratio: 'tall' };
      const buttons = (c.buttons || []).slice(0, 3).map((b) => (b.type === 'web_url'
        ? { type: 'web_url', url: b.url, title: cut(b.title, 20) }
        : { type: 'postback', title: cut(b.title, 20), payload: String(b.payload).slice(0, 1000) }));
      if (buttons.length) e.buttons = buttons;
      return e;
    });
    if (elements.length) out.push(body(p.psid, { attachment: { type: 'template', payload: { template_type: 'generic', elements } } }));
  } else if (p.kind === 'image' && p.url) {
    out.push(body(p.psid, { attachment: { type: 'image', payload: { url: p.url, is_reusable: true } } }));
  }
}
return out;

// Did the agent show products without a tool result? (CARD codes that no tool returned this turn = invented)
// Only when ALL cards are unknown: one strict retry. A mix keeps the real ones (fb_cards.js drops the unknown ones).
const a = $input.first().json;
const codes = [...String(a.output || '').matchAll(/^\s*CARD:\s*([^|\s]+)/gim)].map((m) => m[1]);
const steps = JSON.stringify(a.intermediateSteps || []);
const missing = codes.filter((c) => !steps.includes(c));
return [{ json: { ...a, invented: codes.length > 0 && missing.length === codes.length } }];

// Guided mode (no AI): a card or menu tap -> either reply parts at once, or one Qdrant scroll (fetch=true) for "Guided cards".
const m = $('Is valid message1').first().json;
