// Shared by "Build reply" (fb_cards.js) and "Guided cards" (guided_cards.js): the build puts this file in front of them.
// Product card from Qdrant/tool data + color words ("other colors" = same name without its color words).
const COLOR_WORDS = ['NOIR', 'NOIRE', 'BLANC', 'BLANCHE', 'GRIS', 'GRISE', 'BLEU', 'BLEUE', 'ROUGE', 'VERT', 'VERTE', 'ROSE', 'JAUNE', 'ORANGE',
  'VIOLET', 'VIOLETTE', 'BEIGE', 'MARRON', 'KAKI', 'MARINE', 'CIEL', 'TURQUOISE', 'FUCHSIA', 'DORE', 'DOREE', 'ARGENT', 'ARGENTE', 'OR', 'BORDEAUX',
  'LILAS', 'MAUVE', 'CORAIL', 'PISTACHE', 'MENTHE', 'FLUO', 'CLAIR', 'FONCE', 'BLACK', 'WHITE', 'BLUE', 'RED', 'GREEN', 'PINK', 'YELLOW',
  'PURPLE', 'GREY', 'GRAY', 'BROWN', 'أسود', 'أبيض', 'أزرق', 'أحمر', 'أخضر', 'وردي', 'أصفر', 'بنفسجي', 'رمادي', 'بني'];
const COLOR_RE = new RegExp(`(?<=^|[\\s/,-])(?:${COLOR_WORDS.join('|')})(?=$|[\\s/,-])`, 'g');
const upper = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
const hasColor = (name) => upper(name).replace(COLOR_RE, '\u0000').includes('\u0000');
// Model name = the words before the first color word ("... STABILO POINT 88 GRIS FONCE 88/98" -> "... STABILO POINT 88"):
// it is a substring of every color of the model, so it also works as the Qdrant text search.
const baseName = (name) => {
  const u = upper(name);
  const m = new RegExp(COLOR_RE.source).exec(u);
  return (m ? u.slice(0, m.index) : u).replace(/[\s/,-]+$/, '').replace(/\s+/g, ' ').trim();
};
// "Other types" = models whose name starts with the same words ("STYLO BIC ...", "CNP 3E SEC ...").
// shortcut: name prefix, products have no type tags yet; upgrade with the search v2 tags
const typeKey = (name) => {
  const w = baseName(name).split(/[\s/,()-]+/).filter((x) => x.length >= 2);
  return w.slice(0, w[0] === 'CNP' ? 3 : 2).join(' ');
};

const num = (x) => parseFloat(String(x ?? '').replace(',', '.')) || 0;
const dt = (n) => n.toFixed(3) + ' DT';
const https = (u) => (/^https:\/\//.test(String(u || '')) ? String(u) : '');
// Product photos: only the shop's image server. The catalog sync wrote 2,238 placeholders (https://cdn.example.com/...).
const photo = (u) => (/^https:\/\/([a-z0-9-]+\.)*lebosphore\.tn\//i.test(String(u || '')) ? String(u) : '');
const isActive = (d) => !(d.active === false || String(d.active) === '0');
const labels = (arUi) => (arUi
  ? { pick: '✅ نختار هذا', colors: '🎨 ألوان أخرى', site: '🔗 الموقع', before: 'avant' } // an Arabic word inside "x DT" is reordered by Messenger
  : { pick: '✅ Je choisis', colors: '🎨 Autres couleurs', site: '🔗 Voir le site', before: 'avant' });
const subtitle = (d, arUi) => {
  const now = num(d.price), before = num(d.compare_price);
  const line = before > now && now > 0
    ? `🏷️ -${Math.round(100 - (now * 100) / before)}% ➜ ${dt(now)} (${labels(arUi).before} ${dt(before)})`
    : `💰 ${dt(now)}`;
  return d.promo?.designation ? `${line}\n🎁 ${d.promo.designation}` : line;
};
// Buttons (max 3): pick, other colors (only when the name has a color word), site.
const card = (code, d, arUi, { pick = true } = {}) => {
  const L = labels(arUi);
  const url = https(d.productUrl);
  const c = { title: d.name, subtitle: subtitle(d, arUi), buttons: [] };
  if (pick) c.buttons.push({ type: 'postback', title: L.pick, payload: `pick|${code}` });
  if (pick && hasColor(d.name)) c.buttons.push({ type: 'postback', title: L.colors, payload: `colors|${baseName(d.name)}` });
  if (photo(d.image)) c.image_url = photo(d.image);
  if (url) { c.url = url; c.buttons.push({ type: 'web_url', title: L.site, url }); }
  return c;
};

// Guided mode (no AI): Qdrant products -> Messenger parts. card(), baseName(), typeKey(), hasColor(), isActive() come from card_lib.js.
const plan = $('Guided plan').first().json;
const AR_UI = !/^(French|English)/.test(plan.lang || '');
