  if (!v || typeof v !== 'object') return;
  const name = v.name || v.product_name;
  if (v.code != null && name) {
    const d = products[String(v.code)] || {};
    for (const [k, x] of Object.entries({ ...v, name })) if (x !== null && x !== undefined && x !== '' && d[k] === undefined) d[k] = x;
    products[String(v.code)] = d;
  }
  Object.values(v).forEach(collect);
};
steps.forEach((s) => collect(s.observation));
let summary = '', confirmation = '';
for (const t of texts) {
  if (t.startsWith('PREVIEW OK')) summary = t.slice(t.indexOf('\n') + 1).trim(); // exact summary from Order_product_shopify
  if (t.startsWith('ORDER CREATED')) confirmation = t.slice(t.indexOf('\n') + 1).trim(); // exact confirmation
}

// card(), isActive() come from card_lib.js (put in front of this file by the build)
const L = { choose: AR_UI ? 'اختار من فضلك 👇' : 'Choisissez 👇' };

// ---- read the agent lines ----
// Money comes only from the cards and the code blocks: the AI's own price/total lines and image markdown are dropped.
const MONEY = /(المجموع|💳|🧾|السعر\s*:|\bTotal\s*:|Sous-total|Récapitulatif|\d+(?:[.,]\d{1,3})?\s*(DT|TND|dinars?|دينار|دنانير|د\.ت))/i;
const cards = [], intro = [], outro = [];
let buttons = [], summaryUsed = false, confirmationUsed = false;
for (const line of raw.split('\n')) {
  if (/^\s*REFS:/i.test(line) || /^\s*!\[[^\]]*\]\([^)]*\)\s*$/.test(line)) continue;
  const b = line.match(/^\s*BUTTONS:\s*(.+)$/i);
  if (b) { buttons = [...new Set(b[1].split('|').map((t) => t.trim()).filter(Boolean))].slice(0, 13); continue; }
  const c = line.match(/^\s*CARD:\s*([^|\s]+)/i);
  if (c) {
    const d = products[c[1]];
    if (d && isActive(d) && cards.length < 10 && !cards.some((x) => x.code === c[1])) cards.push({ code: c[1], ...card(c[1], d, AR_UI) });
    continue;
  }
  if (/^\s*SUMMARY\s*$/i.test(line)) { if (summary) (cards.length ? outro : intro).push(summary); summaryUsed = true; continue; }
  if (/^\s*CONFIRMATION\s*$/i.test(line)) { if (confirmation) intro.push(confirmation); confirmationUsed = true; continue; }
  if (MONEY.test(line)) continue;
  (cards.length ? outro : intro).push(line);
}
// The AI forgot the placeholder: the code block is shown anyway, at the top.
if (confirmation && !confirmationUsed) intro.unshift(confirmation);
if (summary && !summaryUsed && !confirmation) intro.unshift(summary);

// Messenger shows no markdown: remove bold/italic markers, keep links readable.
const clean = (lines) => lines.join('\n')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1: $2')
  .replace(/\*\*([^*\n]+)\*\*/g, '$1').replace(/__([^_\n]+)__/g, '$1')
  .replace(/^[ \t]*[-*•][ \t]+/gm, '• ')
  .replace(/\*([^*\n]+)\*/g, '$1').replace(/~([^~\n]+)~/g, '$1')
  // Tunisian shop words (owner): "قرعة" is Algerian -> "دبوزة ماء"; never "طلبية" -> "commande"
  .replace(/(ال)?قرعة( ماء| متاع الماء)?/g, 'دبوزة ماء').replace(/(ال)?طلبي(ة|ات)/g, 'commande')
  .replace(/\n{3,}/g, '\n\n').trim();

// ---- cartable fit, enforced by code (staff: "SB01-XL = 1ère-3ème étatique"; the AI had offered it for a 5ème) ----
// model -> levels from cartable_rules, filled by the build. A model that does not fit the child's level is never shown.
const CARTABLE_FIT = {"SBJ01": {"publique": ["Rawdha"], "privée": ["Rawdha"]}, "TLJ02": {"publique": ["Prépa"], "privée": ["Prépa"]}, "SB02": {"publique": ["1ère", "2ème", "3ème"], "privée": ["1ère"]}, "SB01-XL": {"publique": ["1ère", "2ème", "3ème"], "privée": ["1ère"]}, "SBL01": {"publique": ["1ère", "2ème"], "privée": []}, "SBL02": {"publique": ["3ème", "4ème"], "privée": ["1ère", "2ème", "3ème"]}, "SBH02": {"publique": ["3ème", "4ème"], "privée": ["2ème", "3ème"]}, "SB03": {"publique": ["4ème", "5ème", "6ème"], "privée": ["3ème", "4ème"]}, "SB02-XL": {"publique": ["4ème", "5ème", "6ème"], "privée": ["3ème", "4ème"]}, "SBL03": {"publique": ["5ème", "6ème"], "privée": ["3ème", "4ème"]}, "SBH03": {"publique": ["5ème", "6ème"], "privée": ["3ème", "4ème", "5ème", "6ème"]}, "SD01": {"publique": ["7ème", "8ème"], "privée": ["7ème", "8ème"]}, "SD02": {"publique": ["7ème", "8ème", "9ème"], "privée": ["7ème", "8ème", "9ème"]}, "SD03": {"publique": ["7ème", "8ème", "9ème", "Secondaire"], "privée": ["7ème", "8ème", "9ème", "Secondaire"]}, "SDI": {"publique": ["Secondaire"], "privée": ["Secondaire"]}, "SDIC": {"publique": ["Secondaire"], "privée": ["Secondaire"]}};
const said = (() => { try { return String($('Merge Input Paths1').first().json.chatInput || ''); } catch (e) { return ''; } })();
const prof = (() => { try { return $('Load customer').first().json || {}; } catch (e) { return {}; } })();
const gradeOf = (t) => {
  const s = ` ${String(t || '').toLowerCase()} `;
  if (/روضة|rawdha/.test(s)) return 'Rawdha';
  if (/تحضيري|pr[eé]pa/.test(s)) return 'Prépa';
  if (/ثانوي|secondaire|lyc[eé]e/.test(s)) return 'Secondaire';
  const AR = [['الأولى|الاولى|أولى|اولى', 1], ['الثانية|ثانية', 2], ['الثالثة|ثالثة', 3], ['الرابعة|رابعة', 4], ['الخامسة|خامسة', 5],
    ['السادسة|سادسة', 6], ['السابعة|سابعة', 7], ['الثامنة|ثامنة', 8], ['التاسعة|تاسعة', 9]];
  let n = (AR.find(([w]) => new RegExp(w).test(s)) || [])[1];
  if (!n) n = Number((s.match(/([1-9])\s*(?:ère|ere|ème|eme|e)(?![a-zà-ÿ])/) || s.match(/(?:السنة|سنة|sana|classe|année|annee)\s*([1-9])(?!\d)/) || [])[1]) || 0;
  return n ? (n === 1 ? '1ère' : `${n}ème`) : '';
};
const schoolOf = (t) => (/عموم|[ée]tatique|publi/i.test(t) ? 'publique' : /خاص|priv/i.test(t) ? 'privée' : '');
const grade = gradeOf(said) || gradeOf(prof.child_level);
const school = schoolOf(said) || schoolOf(prof.school_type);
const MODELS = Object.keys(CARTABLE_FIT).sort((a, b) => b.length - a.length); // SB02-XL before SB02
const modelOf = (name) => MODELS.find((k) => new RegExp(`(^|[^A-Z0-9])${k.replace(/[-]/g, '\\-')}($|[^A-Z0-9])`).test(String(name).toUpperCase()));
const levelsOf = (m) => (school ? CARTABLE_FIT[m][school] : [...CARTABLE_FIT[m].publique, ...CARTABLE_FIT[m]['privée']]);
const dropped = [];
if (grade && MODELS.length) {
  for (let i = cards.length - 1; i >= 0; i--) {
    const m = modelOf(cards[i].title);
    if (m && !levelsOf(m).includes(grade)) { if (!dropped.includes(m)) dropped.unshift(m); cards.splice(i, 1); }
  }
}
if (dropped.length) {
  const S = AR_UI ? { publique: 'عمومية', 'privée': 'خاصة' } : { publique: 'publique', 'privée': 'privée' };
  const made = (m) => ['publique', 'privée'].filter((k) => CARTABLE_FIT[m][k].length).map((k) => `${S[k]} ${CARTABLE_FIT[m][k].join(', ')}`).join(' | ');
  const good = MODELS.filter((k) => levelsOf(k).includes(grade)).sort();
  const lvl = grade + (school ? ` (${S[school]})` : '');
  intro.length = 0; // the AI's own claim ("يجيو قد ولدك") is removed with the card
  intro.push(...dropped.map((m) => (AR_UI ? `⚠️ ${m} معمول ل: ${made(m)}، موش ل${lvl}.` : `⚠️ ${m} est fait pour : ${made(m)}, pas pour ${lvl}.`)));
  if (good.length) intro.push(AR_UI ? `🎒 الموديلات المناسبة ل${lvl}: ${good.join(', ')}` : `🎒 Modèles adaptés à ${lvl} : ${good.join(', ')}`);
}

const out = [];
const replies = buttons.map((t) => ({ title: t, payload: `qr|${t}` }));
const question = (text) => (replies.length ? { kind: 'quick_replies', psid, text: text || L.choose, replies } : text && { kind: 'text', psid, text });
if (cards.length) {
  if (clean(intro)) out.push({ kind: 'text', psid, text: clean(intro) });
  out.push({ kind: 'carousel', psid, cards: cards.map(({ code, ...c }) => c) });
  const q = question(clean(outro));
  if (q) out.push(q);
} else {
  const q = question(clean([...intro, ...outro]));
  if (q) out.push(q);
}
if (!out.length) {
  out.push({ kind: 'text', psid, text: AR_UI ? 'نعتذرو، صار مشكل تقني. عاود ابعثلنا رسالتك بعد شوية من فضلك.'
    : 'Désolé, un problème technique est survenu. Merci de renvoyer votre message dans un instant.' });
}
return out.map((json) => ({ json }));

// Reply parts -> exact Messenger Send API bodies, in the same order. One output item = one POST to /me/messages.
// In: { kind: 'text'|'quick_replies'|'carousel'|'image', psid, text, replies[{title,payload}], cards[{title,subtitle,image_url,url,buttons}], url }
// Limits: text 2000, quick replies 13 (title 20), generic template 10 elements (title/subtitle 80, 3 buttons).
const cut = (s, n) => {
  s = String(s ?? '').trim();
  if (s.length <= n) return s;
  let out = '';
  for (const ch of s) { if (out.length + ch.length > n - 1) break; out += ch; } // never splits an emoji
  return out.trimEnd() + '…';
};

// Split on paragraphs, then lines, then hard cut; every part <= 2000.
function split(text, max = 2000) {
  const parts = [];
  let cur = '';
  const push = (s) => { if (s.trim()) parts.push(s.trim()); };
  for (const para of String(text ?? '').split(/\n{2,}/)) {
    const add = cur ? `${cur}\n\n${para}` : para;
    if (add.length <= max) { cur = add; continue; }
    push(cur); cur = '';
    let rest = para;
    while (rest.length > max) {
      let at = rest.lastIndexOf('\n', max);
      if (at < max / 2) at = max;
      push(rest.slice(0, at)); rest = rest.slice(at);
    }
    cur = rest;
  }
  push(cur);
  return parts;
}

const body = (psid, message) => ({ json: { body: { recipient: { id: String(psid) }, messaging_type: 'RESPONSE', message } } });

const out = [];
for (const { json: p } of $input.all()) {
  if (p.kind === 'text' || p.kind === 'quick_replies') {
    const parts = split(p.text);
    const replies = (p.replies || []).slice(0, 13).map((r) => ({ content_type: 'text', title: cut(r.title, 20), payload: String(r.payload).slice(0, 1000) }));
    if (p.kind === 'quick_replies' && !parts.length && replies.length) parts.push('👇');
    parts.forEach((t, i) => {
      const last = i === parts.length - 1;
      out.push(body(p.psid, p.kind === 'quick_replies' && last && replies.length ? { text: t, quick_replies: replies } : { text: t }));
    });
  } else if (p.kind === 'carousel') {
    const elements = (p.cards || []).slice(0, 10).map((c) => {
      const e = { title: cut(c.title, 80) || 'Le Bosphore' };
      if (c.subtitle) e.subtitle = cut(c.subtitle, 80);
      if (c.image_url) e.image_url = c.image_url;
      if (c.url) e.default_action = { type: 'web_url', url: c.url, webview_height_ratio: 'tall' };
      const buttons = (c.buttons || []).slice(0, 3).map((b) => (b.type === 'web_url'
        ? { type: 'web_url', url: b.url, title: cut(b.title, 20) }
        : { type: 'postback', title: cut(b.title, 20), payload: String(b.payload).slice(0, 1000) }));
      if (buttons.length) e.buttons = buttons;
      return e;
    });
    if (elements.length) out.push(body(p.psid, { attachment: { type: 'template', payload: { template_type: 'generic', elements } } }));
  } else if (p.kind === 'image' && p.url) {
    out.push(body(p.psid, { attachment: { type: 'image', payload: { url: p.url, is_reusable: true } } }));
  }
}
return out;

// Did the agent show products without a tool result? (CARD codes that no tool returned this turn = invented)
// Only when ALL cards are unknown: one strict retry. A mix keeps the real ones (fb_cards.js drops the unknown ones).
const a = $input.first().json;
const codes = [...String(a.output || '').matchAll(/^\s*CARD:\s*([^|\s]+)/gim)].map((m) => m[1]);
const steps = JSON.stringify(a.intermediateSteps || []);
const missing = codes.filter((c) => !steps.includes(c));
return [{ json: { ...a, invented: codes.length > 0 && missing.length === codes.length } }];

// Guided mode (no AI): a card or menu tap -> either reply parts at once, or one Qdrant scroll (fetch=true) for "Guided cards".
const m = $('Is valid message1').first().json;
// "<id>#n" = page n of a list ("➕ المزيد"): the plan keeps the page and the list id (gid) for the next "more" button
const [id, pageText] = String(m.guided_id || '').split('#');
const page = Math.max(1, parseInt(pageText, 10) || 1);
const AR_UI = !/^(French|English)/.test(m.lang || '');
const tr = (ar, fr) => (AR_UI ? ar : fr);
const base = { psid: m.psid || m.sender, lang: m.lang || '' };
// only the card fields (Qdrant payloads also hold long descriptions)
const FIELDS = ['name', 'code', 'price', 'compare_price', 'image', 'productUrl', 'active'];
const fetch = (mode, key, body) => [{ json: { ...base, fetch: true, mode, key, page, gid: id, body: { with_payload: FIELDS, with_vector: false, ...body } } }];
const reply = (parts) => parts.map((p) => ({ json: { ...base, fetch: false, psid: base.psid, ...p } }));
const ask = (text, replies) => reply([{ kind: 'quick_replies', text, replies }]);
const name = (text) => ({ key: 'name', match: { text } }); // Qdrant full-text index on name: whole words, any case
const menuReplies = AR_UI
  ? [{ title: '📋 القائمة', payload: 'g|menu' }, { title: '💬 المساعد', payload: 'g|ai' }]
  : [{ title: '📋 Menu', payload: 'g|menu' }, { title: '💬 Assistant', payload: 'g|ai' }];
let mm;

// Main menu: Qdrant `category` values (checked 2026-10-28). Cartables need age/grade questions: they go to the AI.
const CATS = [['📚 Contes', 'Contes'], ['🖊️ Stylos', 'Stylos'], ['📒 Cahiers', 'Cahiers'],
  ['📎 Papeterie', 'Papeterie'], ['🖍️ Coloriages', 'Coloriages'], ['🧳 Valises', 'Valises'], ['🧩 Jeux éducatifs', 'Jeux éducatifs']];
if (id === 'g|menu') {
  // first name from the Facebook profile (BotGenius "Sender name" node); none in the simulator or when the lookup failed
