// 🏫 School books. Public = CNP manuals, named "CNP <year>E <PRI|COL|SEC> <subject> (<section>)"; private = "MP ..." with the class
// (CP, CE1.. or EB1..). Category is unreliable for these (176 CNP books sit in "TAMPONS ET ENCRES"): search by name words.
const YEARS = { PRI: [1, 2, 3, 4, 5, 6], COL: [7, 8, 9], SEC: [1, 2, 3, 4] };
const SECTIONS = { let: ['آداب', 'Lettres'], sci: ['علوم', 'Sciences'], eco: ['اقتصاد', 'Économie'], info: ['إعلامية', 'Informatique'],
  math: ['رياضيات', 'Maths'], exp: ['علوم تجريبية', 'Sc. expériment.'], tech: ['علوم تقنية', 'Sc. techniques'] };
// [class code in names, name words, AR title, FR title]: parents know "السنة الأولى", not "CP"
