  fr: [['🇫🇷 فرنسية', '🇫🇷 Français'], ['FRANCAIS', 'FRANÇAIS', 'الفرنسية', 'فرنسية', 'LECTURE', 'ECRITURE', 'GRAMMAIRE', 'CONJUGAISON', 'ORTHOGRAPHE', 'DICTEE']],
  ar: [['📖 عربية', '📖 Arabe'], ['العربية', 'عربية', 'القراءة', 'قراءة', 'النحو']],
  en: [['🇬🇧 إنجليزية', '🇬🇧 Anglais'], ['ENGLISH', 'ANGLAIS', 'الإنجليزية', 'الانجليزية', 'الأنقليزية']],
  sci: [['🔬 علوم', '🔬 Sciences'], ['علوم', 'العلوم', 'إيقاظ', 'الإيقاظ', 'SCIENCES', 'SCIENCE', 'PHYSIQUE', 'CHIMIE', 'SVT', 'فيزياء', 'الفيزياء']],
  all: [['📚 كل المواد', '📚 Toutes'], []],
};
if (id === 'g|para') {
  return ask(tr('الكتب الموازية لأنا مستوى؟ 👇', 'Parascolaire : quel niveau ? 👇'), PARA_LEVELS.map(([a, f, l]) => ({ title: tr(a, f), payload: `${id}|${l}` })));
}
if ((mm = id.match(/^g\|para\|(PREP|PRIM|COL|SEC)$/))) {
  return ask(tr('في أنا مادة؟ 👇', 'Quelle matière ? 👇'), Object.entries(SUBJECTS).map(([k, [t]]) => ({ title: tr(...t), payload: `${id}|${k}` })));
}
if ((mm = id.match(/^g\|para\|(PREP|PRIM|COL|SEC)\|(\w+)$/)) && SUBJECTS[mm[2]]) {
  const words = SUBJECTS[mm[2]][1];
  // COL/SEC also start CNP manual names ("CNP 8E COL"): those are school books, not parascolaire
  return fetch('para', `${mm[1]}|${mm[2]}`, { limit: 300, filter: { must: [name(mm[1])], must_not: [name('CNP')], ...(words.length ? { should: words.map(name) } : {}) } });
}

// 🛒 "take them all": show the basket (names, prices, total) before the commande starts
if (id.startsWith('basket|')) {
  const codes = id.slice(7).split(',').filter(Boolean).slice(0, 20);
  return fetch('basket', codes.join(','), { limit: 50, filter: { must: [{ key: 'code', match: { any: codes } }] } });
}
if (id === 'g|ai') {
  return reply([{ kind: 'text', text: tr('تفضل، اكتبلنا شنوة تلوج (كتاب، أدوات، هدية...) و نعاونك 😊',
    'Je vous écoute : écrivez ce que vous cherchez (livre, fournitures, cadeau...) 😊') }]);
}
if (id.startsWith('g|cat|')) {
  // shortcut: the 300 first points of the category are ranked (no Qdrant sort on discount); fine for a menu
  return fetch('cat', id.slice(6), { limit: 300, filter: { must: [{ key: 'category', match: { value: id.slice(6) } }] } });
}
if (id === 'g|promos') {
  return fetch('promos', '', { limit: 1000, filter: { should: [...CATS.map(([, cat]) => cat), 'Parascolaire'].map((value) => ({ key: 'category', match: { value } })) } });
}
if (id.startsWith('pick|')) {
  return fetch('pick', id.slice(5), { limit: 5, filter: { must: [{ key: 'code', match: { value: id.slice(5) } }] } });
}
if (id.startsWith('colors|')) {
  // all names that contain the model name; "Guided cards" keeps the ones with exactly the same base name
  return fetch('colors', id.slice(7), { limit: 100, filter: { must: [name(id.slice(7))] } });
}
if (id.startsWith('types|')) { // other models of the same type (typeKey in card_lib.js)
  return fetch('types', id.slice(6), { limit: 100, filter: { must: [name(id.slice(6))] } });
}
return ask(tr('شنوة تحب نعاونك بيه؟ 👇', 'Comment puis-je vous aider ? 👇'), menuReplies);

// Shared by "Build reply" (fb_cards.js) and "Guided cards" (guided_cards.js): the build puts this file in front of them.
// Product card from Qdrant/tool data + color words ("other colors" = same name without its color words).
const COLOR_WORDS = ['NOIR', 'NOIRE', 'BLANC', 'BLANCHE', 'GRIS', 'GRISE', 'BLEU', 'BLEUE', 'ROUGE', 'VERT', 'VERTE', 'ROSE', 'JAUNE', 'ORANGE',
  'VIOLET', 'VIOLETTE', 'BEIGE', 'MARRON', 'KAKI', 'MARINE', 'CIEL', 'TURQUOISE', 'FUCHSIA', 'DORE', 'DOREE', 'ARGENT', 'ARGENTE', 'OR', 'BORDEAUX',
  'LILAS', 'MAUVE', 'CORAIL', 'PISTACHE', 'MENTHE', 'FLUO', 'CLAIR', 'FONCE', 'BLACK', 'WHITE', 'BLUE', 'RED', 'GREEN', 'PINK', 'YELLOW',
  'PURPLE', 'GREY', 'GRAY', 'BROWN', 'أسود', 'أبيض', 'أزرق', 'أحمر', 'أخضر', 'وردي', 'أصفر', 'بنفسجي', 'رمادي', 'بني'];
const COLOR_RE = new RegExp(`(?<=^|[\\s/,-])(?:${COLOR_WORDS.join('|')})(?=$|[\\s/,-])`, 'g');
const upper = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();
const hasColor = (name) => upper(name).replace(COLOR_RE, '\u0000').includes('\u0000');
// Model name = the words before the first color word ("... STABILO POINT 88 GRIS FONCE 88/98" -> "... STABILO POINT 88"):
// it is a substring of every color of the model, so it also works as the Qdrant text search.
const baseName = (name) => {
  const u = upper(name);
  const m = new RegExp(COLOR_RE.source).exec(u);
  return (m ? u.slice(0, m.index) : u).replace(/[\s/,-]+$/, '').replace(/\s+/g, ' ').trim();
};
// "Other types" = models whose name starts with the same words ("STYLO BIC ...", "CNP 3E SEC ...").
// shortcut: name prefix, products have no type tags yet; upgrade with the search v2 tags
const typeKey = (name) => {
  const w = baseName(name).split(/[\s/,()-]+/).filter((x) => x.length >= 2);
  return w.slice(0, w[0] === 'CNP' ? 3 : 2).join(' ');
};

const num = (x) => parseFloat(String(x ?? '').replace(',', '.')) || 0;
const dt = (n) => n.toFixed(3) + ' DT';
const https = (u) => (/^https:\/\//.test(String(u || '')) ? String(u) : '');
// Product photos: only the shop's image server. The catalog sync wrote 2,238 placeholders (https://cdn.example.com/...).
const photo = (u) => (/^https:\/\/([a-z0-9-]+\.)*lebosphore\.tn\//i.test(String(u || '')) ? String(u) : '');
const isActive = (d) => !(d.active === false || String(d.active) === '0');
const labels = (arUi) => (arUi
  ? { pick: '✅ نختار هذا', colors: '🎨 ألوان أخرى', site: '🔗 الموقع', before: 'avant' } // an Arabic word inside "x DT" is reordered by Messenger
  : { pick: '✅ Je choisis', colors: '🎨 Autres couleurs', site: '🔗 Voir le site', before: 'avant' });
const subtitle = (d, arUi) => {
  const now = num(d.price), before = num(d.compare_price);
  const line = before > now && now > 0
    ? `🏷️ -${Math.round(100 - (now * 100) / before)}% ➜ ${dt(now)} (${labels(arUi).before} ${dt(before)})`
    : `💰 ${dt(now)}`;
  return d.promo?.designation ? `${line}\n🎁 ${d.promo.designation}` : line;
};
// Buttons (max 3): pick, other colors (only when the name has a color word), site.
const card = (code, d, arUi, { pick = true } = {}) => {
  const L = labels(arUi);
  const url = https(d.productUrl);
  const c = { title: d.name, subtitle: subtitle(d, arUi), buttons: [] };
  if (pick) c.buttons.push({ type: 'postback', title: L.pick, payload: `pick|${code}` });
  if (pick && hasColor(d.name)) c.buttons.push({ type: 'postback', title: L.colors, payload: `colors|${baseName(d.name)}` });
  if (photo(d.image)) c.image_url = photo(d.image);
  if (url) { c.url = url; c.buttons.push({ type: 'web_url', title: L.site, url }); }
  return c;
};

// Guided mode (no AI): Qdrant products -> Messenger parts. card(), baseName(), typeKey(), hasColor(), isActive() come from card_lib.js.
const plan = $('Guided plan').first().json;
const AR_UI = !/^(French|English)/.test(plan.lang || '');
const psid = plan.psid;
const page = Math.max(1, Number(plan.page) || 1);
const all = $input.all().flatMap((i) => i.json?.result?.points || []).map((p) => p.payload || {});
const products = [];
for (const d of all) if (d.code != null && d.name && isActive(d) && !products.some((x) => String(x.code) === String(d.code))) products.push(d);
const T = AR_UI
  ? { gone: 'المنتوج هذا موش متوفر توا 😕 تحب نلوجلك على حاجة شبيهة؟', next: 'شنوة تحب تعمل؟ 👇', order: '✅ نكمل الـ commande',
      colors: '🎨 ألوان أخرى', types: '🔁 أنواع أخرى', menu: '📋 القائمة', ai: '💬 المساعد', pickColor: 'اختار اللون اللي يعجبك 👆', one: 'هذا اللون الوحيد المتوفر توا.',
      more: 'عجبك حاجة؟ اضغط "✅ نختار هذا"، ولا ارجع للقائمة 👇', moreBtn: '➕ المزيد', pack: (n) => `🛒 نحب الكل (${n})`,
      empty: 'ما لقيت حتى منتوج في القسم هذا توا 😕', noPromo: 'ما فماش promo توا 😕', noMore: 'هذا كل شي عندنا في القسم هذا 👌',
      books: 'هاذم الكتب المتوفرة 📚 تنجم تختار كتاب كتاب، ولا تاخذ الكل مرة وحدة 👇' }
  : { gone: "Ce produit n'est plus disponible 😕 Voulez-vous un produit similaire ?", next: 'Que souhaitez-vous faire ? 👇',
      order: '✅ Commander', colors: '🎨 Autres couleurs', types: '🔁 Autres modèles', menu: '📋 Menu', ai: '💬 Assistant', pickColor: 'Choisissez votre couleur 👆',
      one: 'C\'est la seule couleur disponible pour le moment.', more: 'Un article vous plaît ? Touchez "✅ Je choisis", ou revenez au menu 👇',
      moreBtn: '➕ Voir plus', pack: (n) => `🛒 Tout prendre (${n})`,
      empty: 'Aucun article dans ce rayon pour le moment 😕', noPromo: 'Pas de promo pour le moment 😕', noMore: "C'est tout pour ce rayon 👌",
      books: 'Voici les livres disponibles 📚 Choisissez-les un par un, ou prenez tout en une fois 👇' };
const menu = [{ title: T.menu, payload: 'g|menu' }, { title: T.ai, payload: 'g|ai' }];
const out = [];

// Lycée sections, read from the "(...)" tag of a CNP name. No tag (or an unknown one like "(anglais)") = book for every section.
const SECTION_RE = { let: /آداب|lettre/i, math: /math|رياضيات/i, exp: /exp|تجريبية/i, tech: /sc\.?\s*tech|تقنية/i,
  info: /inf|إعلامية|الاعلامية|الإعلامية/i, eco: /[eé]co|اقتصاد|gest/i, sci: /scien/i };
const NOT_LETTRES = /autres que|ما عد|علمية/i; // "(autres que lettres)", "(كافة الشعب ما عدى الآداب)", "(شعب علمية)"
const forSection = (bookName, section) => {
  if (!section) return true;
  const tag = (String(bookName).match(/\(([^)]*)\)/) || [])[1];
  if (!tag) return true;
  if (NOT_LETTRES.test(tag)) return section !== 'let';
  const hits = Object.keys(SECTION_RE).filter((k) => SECTION_RE[k].test(tag));
  return !hits.length || hits.includes(section);
};

if (plan.mode === 'pick') {
  const d = products.find((x) => String(x.code) === String(plan.key));
  if (!d) return [{ json: { kind: 'quick_replies', psid, text: T.gone, replies: menu } }]; // old card: product gone or inactive
  out.push({ kind: 'carousel', psid, cards: [card(d.code, d, AR_UI, { pick: false })] });
  const type = typeKey(d.name);
  out.push({ kind: 'quick_replies', psid, text: T.next, replies: [
    { title: T.order, payload: `g|order|${d.code}` },
    ...(hasColor(d.name) ? [{ title: T.colors, payload: `colors|${baseName(d.name)}` }] : []),
    ...(type ? [{ title: T.types, payload: `types|${type}` }] : []),
    { title: T.menu, payload: 'g|menu' }] });
} else if (plan.mode === 'colors') {
  const same = products.filter((d) => baseName(d.name) === plan.key).slice(0, 10);
  if (!same.length) return [{ json: { kind: 'quick_replies', psid, text: T.gone, replies: menu } }];
  out.push({ kind: 'carousel', psid, cards: same.map((d) => card(d.code, d, AR_UI)) });
  out.push({ kind: 'quick_replies', psid, text: same.length === 1 ? T.one : T.pickColor, replies: menu });
} else if (plan.mode === 'basket') {
  // 🛒 the chosen items, in the chosen order: name + price + total, so the customer sees everything before the commande
  const B = AR_UI
    ? { head: (n) => `🛒 الحاجات اللي اخترتهم (${n}):`, sum: 'المجموع', noDel: '(من غير التوصيل)', miss: (n) => `⚠️ ${n} منتوج موش متوفر توا، ما تحسبش في المجموع.` }
    : { head: (n) => `🛒 Votre sélection (${n}) :`, sum: 'Total', noDel: '(hors livraison)', miss: (n) => `⚠️ ${n} article(s) indisponible(s), non compté(s).` };
  const iso = (s) => (AR_UI ? `⁦${s}⁩` : s); // Latin names and amounts keep their order in an Arabic message
  const want = String(plan.key).split(',').filter(Boolean);
  const got = want.map((c) => products.find((d) => String(d.code) === c)).filter(Boolean);
  if (!got.length) return [{ json: { kind: 'quick_replies', psid, text: T.gone, replies: menu } }];
  const total = got.reduce((s, d) => s + num(d.price), 0);
  const text = [B.head(got.length), ...got.map((d) => `• ${iso(`${d.name} — ${dt(num(d.price))}`)}`),
    `💰 ${B.sum}: ${iso(dt(total))} ${B.noDel}`, want.length > got.length && B.miss(want.length - got.length)].filter(Boolean).join('\n');
  out.push({ kind: 'quick_replies', psid, text, replies: [{ title: T.order, payload: `g|order|${got.map((d) => d.code).join(',')}` }, menu[0]] });
} else { // lists: cat, promos, books, para, types -> 10 cards per page, "➕ المزيد" for the next page
  const disc = (d) => { const now = num(d.price), before = num(d.compare_price); return before > now && now > 0 ? 1 - now / before : 0; };
  const seen = new Set(); // one card per model: its colors are behind "🎨 ألوان أخرى"
  let pool = products;
  if (plan.mode === 'promos') pool = pool.filter((d) => disc(d) > 0);
  if (plan.mode === 'books') pool = pool.filter((d) => forSection(d.name, String(plan.key).split('|')[2]));
  const list = (plan.mode === 'books'
    ? pool.sort((a, b) => String(a.name).localeCompare(String(b.name))) // the year's books by subject name
    : pool.sort((a, b) => Number(Boolean(photo(b.image))) - Number(Boolean(photo(a.image))) || disc(b) - disc(a))) // photo first, then promo
    .filter((d) => !seen.has(baseName(d.name)) && seen.add(baseName(d.name)));
  const shown = list.slice((page - 1) * 10, page * 10);
  if (!shown.length) {
    const text = page > 1 ? T.noMore : plan.mode === 'promos' ? T.noPromo : T.empty;
    return [{ json: { kind: 'quick_replies', psid, text, replies: menu } }];
  }
  out.push({ kind: 'carousel', psid, cards: shown.map((d) => card(d.code, d, AR_UI)) });
  const replies = [];
  if (list.length > page * 10) replies.push({ title: T.moreBtn, payload: `${plan.gid}#${page + 1}` });
  // a parent buys the whole year: one tap -> commande with every book (CNP / private class lists only, max 12)
  if (plan.mode === 'books' && page === 1 && list.length > 1 && list.length <= 12) {
    replies.push({ title: T.pack(list.length), payload: `basket|${list.map((d) => d.code).join(',')}` }); // basket view first
  }
  out.push({ kind: 'quick_replies', psid, text: plan.mode === 'books' && page === 1 ? T.books : T.more, replies: [...replies, ...menu] });
}
return out.map((json) => ({ json }));

// Menu choices that describe the customer (school, level, section, boy/girl) are saved at once, without the AI.
// Runs on every message: the last cartable tap goes to the AI, its payload still holds gender + year + school.
const m = $('Is valid message1').first().json;
const id = String(m.payload || m.guided_id || '').split('#')[0];
const CYCLE = { PRI: 'primaire', COL: 'collège', SEC: 'lycée' };
const BAG = { rawdha: 'rawdha', college: 'collège', secondaire: 'lycée' };
const f = {};
let mm;
if ((mm = id.match(/^g\|school\|(pub|priv)(?:\|(\w+))?(?:\|(\d))?(?:\|(\w+))?$/))) {
  f.school_type = mm[1] === 'pub' ? 'publique' : 'privée';
  if (mm[1] === 'priv' && mm[2]) f.child_level = mm[2];
  if (mm[1] === 'pub' && mm[2]) f.child_level = CYCLE[mm[2]] + (mm[3] ? ` ${mm[3]}e année` : '');
  if (mm[4]) f.section = mm[4];
} else if ((mm = id.match(/^g\|bag\|(boy|girl)(?:\|(rawdha|primaire|college|secondaire))?(?:\|([1-6]))?(?:\|(pub|priv))?$/))) {
  f.child_gender = mm[1] === 'boy' ? 'garçon' : 'fille';
  if (mm[2] === 'primaire' && mm[3]) f.child_level = `primaire ${mm[3]}e année`;
  else if (mm[2] && mm[2] !== 'primaire') f.child_level = BAG[mm[2]];
  if (mm[4]) f.school_type = mm[4] === 'pub' ? 'publique' : 'privée';
}
return Object.keys(f).length ? [{ json: { psid: m.psid, fields: JSON.stringify(f) } }] : [];

// Flood limit: max 20 AI answers per customer in 10 min (each answer costs Gemini).
// The 21st message gets one polite notice; after it: silence (no output) until older turns leave the window.
const LIMIT = 20, WINDOW = 10 * 60e3;
const m = $('Is valid message1').first().json;
const recent = $input.all().map((i) => i.json).filter((r) => r && r.psid && Date.now() - Number(r.ts) < WINDOW).length;
if (recent > LIMIT) return [];
if (recent < LIMIT) return [{ json: { flood: false, psid: m.psid } }];
const FR = /^(French|English)/.test(m.lang || '');
return [{ json: { flood: true, kind: 'text', psid: m.psid, text: FR
  ? 'Nous avons reçu beaucoup de messages en peu de temps 🙏 Merci de réessayer dans 10 minutes.'
  : 'وصلتنا برشا رسائل في وقت قصير 🙏 عاود ابعثلنا بعد 10 دقايق من فضلك.' } }];

// The AI failed after its retries (Gemini 503/429/timeout): the customer gets a short "send it again" + menu, never silence.
// No technical text: the error stays in the n8n run.
const m = $('Is valid message1').first().json;
const fr = /^French/.test(m.lang || ''), en = /^English/.test(m.lang || '');
const text = fr ? 'Désolé, un petit souci de notre côté 🙏 Renvoyez votre message dans un instant, ou choisissez dans le menu 👇'
  : en ? 'Sorry, a small problem on our side 🙏 Please send your message again in a moment, or pick from the menu 👇'
  : 'سامحني، صار مشكل صغير عندنا 🙏 عاود ابعثلي رسالتك بعد شوية، ولا اختار من القائمة 👇';
return [{ json: { kind: 'quick_replies', psid: m.psid || m.sender, text,
  replies: [{ title: fr || en ? '📋 Menu' : '📋 القائمة', payload: 'g|menu' }] } }];
